-- Generated by scripts/build_compiled.py from src/fraudrules/rules/instant-payment/ip-004-new-payee-after-device-or-sim-change.yaml. Do not edit.
-- IP-004 First instant payment to a new payee within a day of a new device or SIM change
SELECT DISTINCT 'IP-004' AS rule_id, 'transactions' AS anchor_table, s1.id AS anchor_id
FROM transactions AS s1
JOIN events AS s0 ON s0.customer_id = s1.customer_id AND s0.ts < s1.ts AND s0.ts > s1.ts - 86400 AND ((s0.event_type = 'sim_change' AND s0.outcome = 'success') OR (s0.event_type = 'login' AND s0.outcome = 'success' AND s0.device_new = 1))
WHERE (s1.direction = 'out' AND s1.channel IN ('rtp', 'fednow', 'p2p') AND s1.counterparty_new = 1 AND s1.amount_cents >= 50000);
